package br.com.onda;
import android.content.*;import android.graphics.*;import android.media.ExifInterface;import android.net.Uri;import android.os.ParcelFileDescriptor;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;import org.json.*;
/** User-picked inputs only. No file-size/count cap; bounded decode memory and no writes to originals. */
final class LocalAiPhotos {
 static Bitmap load(Context c,Uri uri,int edge,LocalAiModels.Cancel cancel)throws IOException{cancel.check();Bitmap image=null;try{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;try(InputStream in=c.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Foto indisponível");BitmapFactory.decodeStream(in,null,bounds);}if(bounds.outWidth<=0||bounds.outHeight<=0)throw new IOException("O Android não conseguiu ler esta foto. Escolha outra imagem ou exporte-a em um formato compatível.");BitmapFactory.Options options=new BitmapFactory.Options();options.inPreferredConfig=Bitmap.Config.ARGB_8888;options.inScaled=false;options.inSampleSize=1;while(options.inSampleSize<(1<<28)&&(bounds.outWidth/(options.inSampleSize*2)>edge||bounds.outHeight/(options.inSampleSize*2)>edge))options.inSampleSize*=2;cancel.check();try(InputStream in=c.getContentResolver().openInputStream(uri)){image=BitmapFactory.decodeStream(in,null,options);}if(image==null)throw new IOException("Não foi possível abrir a foto selecionada.");Matrix transform=new Matrix();try(ParcelFileDescriptor descriptor=c.getContentResolver().openFileDescriptor(uri,"r")){if(descriptor!=null){int orientation=new ExifInterface(descriptor.getFileDescriptor()).getAttributeInt(ExifInterface.TAG_ORIENTATION,ExifInterface.ORIENTATION_NORMAL);switch(orientation){case 2:transform.setScale(-1,1);break;case 3:transform.setRotate(180);break;case 4:transform.setScale(1,-1);break;case 5:transform.setRotate(90);transform.postScale(-1,1);break;case 6:transform.setRotate(90);break;case 7:transform.setRotate(270);transform.postScale(-1,1);break;case 8:transform.setRotate(270);break;}}}catch(IOException|RuntimeException ignored){}if(!transform.isIdentity()){Bitmap rotated=Bitmap.createBitmap(image,0,0,image.getWidth(),image.getHeight(),transform,true);if(rotated!=image){image.recycle();image=rotated;}}cancel.check();return image;}catch(RuntimeException|OutOfMemoryError e){if(image!=null)image.recycle();throw new IOException("Não foi possível preparar esta foto neste aparelho. O original foi mantido.",e);}catch(IOException e){if(image!=null)image.recycle();throw e;}}
 static File selection(Context c,List<Uri> photos)throws IOException{File request=new File(c.getCacheDir(),"onda-ai-photos-"+UUID.randomUUID()+".json");JSONArray list=new JSONArray();for(Uri uri:photos)list.put(uri.toString());Files.write(request.toPath(),list.toString().getBytes(StandardCharsets.UTF_8));return request;}
 static List<Uri> restore(Context c,String name){ArrayList<Uri> photos=new ArrayList<>();if(name==null||!name.matches("onda-ai-photos-[a-f0-9-]{36}\\.json"))return photos;try{JSONArray list=new JSONArray(new String(Files.readAllBytes(new File(c.getCacheDir(),name).toPath()),StandardCharsets.UTF_8));for(int i=0;i<list.length();i++){Uri uri=Uri.parse(list.getString(i));if("content".equals(uri.getScheme()))photos.add(uri);}}catch(Exception ignored){}return photos;}
}
